import sys

def count_primes(n):
    if n < 3:
        return 0
    try:
        import numpy as np
    except Exception:
        np = None
    if np is not None and n >= 1000:
        half = (n + 1) // 2
        sieve = np.ones(half, dtype=bool)
        sieve[0] = False
        limit = int(n ** 0.5)
        i = 1
        while 2 * i + 1 <= limit:
            if sieve[i]:
                p = 2 * i + 1
                start = (p * p) // 2
                sieve[start::p] = False
